Theorem cmalloc_g cs n :
  SH cs -> 0 <= n -> size_overflows n = false ->
  gtree (elen_ok n (pot cs + AMC)) EVM (CALLB n (pot cs + AMC)) (cmalloc cs n)
        (fun r => snd r <> None /\ pot (fst r) <= pot cs + AMC).
Proof.
